mapper.select:
SELECT E.uuid, E.SVR_ASSET_CODE svrAssetCode, E.SADAS_ASSET_CODE sadasAssetCode, I.ASSET_NAME assetName FROM chb_asset_mapping_ex E LEFT JOIN CHB_ASSET_INFO I ON E.SVR_ASSET_CODE = I.ASSET_CODE AND I.STATUS IN ('E','M')
#{item}
AND SADAS_ASSET_CODE LIKE concat_ws('','%',#{sadasAssetCode},'%')
AND uuid = #{uuid}
ORDER BY e.UPDATE_TIME

mapper.update:
update chb_asset_mapping_ex
SET SVR_ASSET_CODE = #{svrAssetCode},
SADAS_ASSET_CODE = #{sadasAssetCode}
where uuid =  #{uuid}

UPDATE CHB_BOT_AST_POS P
SET PLAN_ASSET_ID = #{svrAssetCode}
WHERE PLAN_ASSET_ID = #{sadasAssetCode}

UPDATE CHB_BOT_AST_POS P,chb_asset_mapping_ex E
SET PLAN_ASSET_ID = #{svrAssetCode}
WHERE P.PLAN_ASSET_ID = E.SVR_ASSET_CODE
AND E.SADAS_ASSET_CODE = #{sadasAssetCode}

UPDATE CHB_BOT_AST_POS P,chb_asset_mapping_ex E
SET PLAN_ASSET_ID = #{sadasAssetCode}
WHERE P.PLAN_ASSET_ID = E.SVR_ASSET_CODE
AND E.SADAS_ASSET_CODE = #{sadasAssetCode}

